from scipy.optimize import linear_sum_assignment
# Persistent per-input state: tracks=[], next_id=1. Each track has id, box, score, misses=0, hits=1, trail=[center].
def center(box):
    x1, y1, x2, y2 = box
    return (int((x1 + x2) / 2), int((y1 + y2) / 2))
def iou(a, b):
    ax1, ay1, ax2, ay2 = a; bx1, by1, bx2, by2 = b
    inter = max(0, min(ax2, bx2) - max(ax1, bx1)) * max(0, min(ay2, by2) - max(ay1, by1))
    area_a = max(0, ax2 - ax1) * max(0, ay2 - ay1)
    area_b = max(0, bx2 - bx1) * max(0, by2 - by1)
    union = area_a + area_b - inter
    return inter / union if union > 0 else 0.0
def new_track(det):
    global next_id
    t = {'id': next_id, 'box': det['box'], 'score': det['score'], 'misses': 0, 'hits': 1, 'trail': [center(det['box'])]}
    next_id += 1
    return t
if not tracks:
    for det in detections: tracks.append(new_track(det))
else:
    if detections:
        cost = np.zeros((len(tracks), len(detections)))
        for i, trk in enumerate(tracks):
            for j, det in enumerate(detections): cost[i, j] = 1 - iou(trk['box'], det['box'])
        row_idx, col_idx = linear_sum_assignment(cost)
    else:
        row_idx, col_idx = np.array([], dtype=int), np.array([], dtype=int)
    matched_tracks, matched_dets = set(), set()
    for r, c in zip(row_idx, col_idx):
        if 1 - cost[r, c] >= parameters['iou_threshold']:
            t, det = tracks[r], detections[c]
            t['box'], t['score'] = det['box'], det['score']
            t['hits'] += 1; t['misses'] = 0
            t['trail'].append(center(t['box']))
            t['trail'] = t['trail'][-parameters['trail_length']:]
            matched_tracks.add(r); matched_dets.add(c)
    for i, t in enumerate(tracks):
        if i not in matched_tracks: t['misses'] += 1
    for j, det in enumerate(detections):
        if j not in matched_dets: tracks.append(new_track(det))
    tracks = [t for t in tracks if t['misses'] <= parameters['max_age']]
# Retain missed tracks internally for association, but current-frame consumers receive observations only.
return [{'id': t['id'], 'box': t['box'], 'score': t['score'], 'hits': t['hits'], 'trail': list(t['trail'])} for t in tracks if t['misses'] == 0]

# Detector labels are 'helmet' (hard hat) and 'Vest' (vest); neither model detects PPE usage directly.
def overlap(a, b):
    return max(0.0, min(a[2], b[2]) - max(a[0], b[0])) * max(0.0, min(a[3], b[3]) - max(a[1], b[1]))
assigned = {t['id']: {'hard hat': None, 'vest': None} for t in tracks}
for item, label in [('hard hat', 'helmet'), ('vest', 'Vest')]:
    candidates = []
    for j, det in enumerate(ppe_detections):
        if det['label'] != label: continue
        x1, y1, x2, y2 = det['box']
        cx, cy = (x1 + x2) / 2, (y1 + y2) / 2
        for t in tracks:
            bx1, by1, bx2, by2 = t['box']
            height = by2 - by1
            if height <= 0 or bx2 <= bx1: continue
            if item == 'hard hat': region = [bx1, by1, bx2, by1 + 0.35 * height]
            else: region = [bx1, by1 + 0.20 * height, bx2, by1 + 0.80 * height]
            if region[0] <= cx <= region[2] and region[1] <= cy <= region[3]:
                quality = overlap(det['box'], region) / max(1e-9, (x2 - x1) * (y2 - y1))
                candidates.append((quality, det['score'], j, t['id']))
    used_detections = set()
    for quality, score, j, tid in sorted(candidates, reverse=True):
        if j not in used_detections and assigned[tid][item] is None:
            assigned[tid][item] = {'box': ppe_detections[j]['box'], 'score': score, 'label': label}
            used_detections.add(j)
result = []
for t in tracks:
    items = assigned[t['id']]
    missing = [item for item in parameters['required_items'] if items[item] is None]
    result.append({'track_id': t['id'], 'box': t['box'], 'required_items': list(parameters['required_items']), 'detected_items': {k: v for k, v in items.items() if v is not None}, 'missing_items': missing, 'compliant': len(missing) == 0})
return result

